const std = @import("std");

pub fn main() !void {
    const nums = [_]i32{ 42, 17, 8, 99, 3, 56, 71, 24 };

    var max: i32 = nums[0];
    var min: i32 = nums[0];

    for (nums) |n| {
        if (n > max) max = n;
        if (n < min) min = n;
    }

    std.debug.print("Max: {}\n", .{max});
    std.debug.print("Min: {}\n", .{min});
}
